const input = $input.first().json;

const today = new Intl.DateTimeFormat(
  'en-CA',
  {
    timeZone: 'Asia/Shanghai',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit'
  }
).format(new Date());

const requestedDate = String(
  input.body?.report_date ??
  input.query?.report_date ??
  ''
).trim();

function isValidDate(value) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) {
    return false;
  }

  const parsed = new Date(`${value}T00:00:00Z`);

  return (
    !Number.isNaN(parsed.getTime()) &&
    parsed.toISOString().slice(0, 10) === value
  );
}

if (requestedDate && !isValidDate(requestedDate)) {
  throw new Error(
    'report_date must be a valid YYYY-MM-DD date'
  );
}

const isManualReplay = Boolean(
  input.headers ||
  input.webhookUrl ||
  input.body
);

return [
  {
    json: {
      report_date: requestedDate || today,
      trigger_source: isManualReplay
        ? 'manual_replay'
        : 'schedule',
      data_source: 'fixed_test_data',
      timezone: 'Asia/Shanghai',
      generated_at: new Date().toISOString()
    }
  }
];

const context = $input.first().json;

const allRuns = [
  {
    report_date: '2026-09-01',
    event_id: 'mail-report-001',
    status: 'succeeded',
    category: 'product',
    elapsed_time: 4.0,
    total_tokens: 720
  },
  {
    report_date: '2026-09-01',
    event_id: 'mail-report-002',
    status: 'succeeded',
    category: 'technical',
    elapsed_time: 6.0,
    total_tokens: 900
  },
  {
    report_date: '2026-09-01',
    event_id: 'mail-report-003',
    status: 'succeeded',
    category: 'product',
    elapsed_time: 3.0,
    total_tokens: 640
  },
  {
    report_date: '2026-09-01',
    event_id: 'mail-report-004',
    status: 'succeeded',
    category: 'other',
    elapsed_time: 5.0,
    total_tokens: 800
  },
  {
    report_date: '2026-09-01',
    event_id: 'mail-report-005',
    status: 'failed',
    category: 'sensitive',
    elapsed_time: 2.0,
    total_tokens: 0
  },
  {
    report_date: '2026-09-01',
    event_id: 'mail-report-006',
    status: 'failed',
    category: 'technical',
    elapsed_time: 4.0,
    total_tokens: 0
  },
  {
    report_date: '2026-09-02',
    event_id: 'mail-report-007',
    status: 'succeeded',
    category: 'product',
    elapsed_time: 4.5,
    total_tokens: 700
  },
  {
    report_date: '2026-09-02',
    event_id: 'mail-report-008',
    status: 'succeeded',
    category: 'technical',
    elapsed_time: 5.5,
    total_tokens: 850
  },
  {
    report_date: '2026-09-02',
    event_id: 'mail-report-009',
    status: 'failed',
    category: 'sensitive',
    elapsed_time: 2.0,
    total_tokens: 0
  }
];

const selectedRuns = allRuns.filter(
  (run) => run.report_date === context.report_date
);

return [
  {
    json: {
      ...context,
      available_dates: [
        '2026-09-01',
        '2026-09-02'
      ],
      runs: selectedRuns
    }
  }
];

const data = $input.first().json;
const runs = Array.isArray(data.runs)
  ? data.runs
  : [];

const statusDistribution = {
  succeeded: 0,
  failed: 0
};

const categoryDistribution = {
  product: 0,
  technical: 0,
  sensitive: 0,
  other: 0
};

let elapsedTimeSum = 0;
let totalTokens = 0;

for (const run of runs) {
  const status = String(
    run.status ?? 'unknown'
  ).toLowerCase();

  const category = String(
    run.category ?? 'other'
  ).toLowerCase();

  if (status in statusDistribution) {
    statusDistribution[status] += 1;
  }

  if (!(category in categoryDistribution)) {
    categoryDistribution[category] = 0;
  }

  categoryDistribution[category] += 1;

  elapsedTimeSum += Number(
    run.elapsed_time ?? 0
  );

  totalTokens += Number(
    run.total_tokens ?? 0
  );
}

const totalRuns = runs.length;
const succeededRuns =
  statusDistribution.succeeded;
const failedRuns =
  statusDistribution.failed;

const successRate = totalRuns > 0
  ? Number(
      (
        succeededRuns /
        totalRuns *
        100
      ).toFixed(2)
    )
  : 0;

const averageElapsedTime = totalRuns > 0
  ? Number(
      (
        elapsedTimeSum /
        totalRuns
      ).toFixed(2)
    )
  : 0;

return [
  {
    json: {
      day: 40,
      report_date: data.report_date,
      trigger_source: data.trigger_source,
      data_source: data.data_source,
      timezone: data.timezone,
      generated_at: data.generated_at,
      has_data: totalRuns > 0,
      total_runs: totalRuns,
      succeeded_runs: succeededRuns,
      failed_runs: failedRuns,
      success_rate: successRate,
      average_elapsed_time:
        averageElapsedTime,
      total_tokens: totalTokens,
      status_distribution:
        statusDistribution,
      category_distribution:
        categoryDistribution,
      failed_event_ids: runs
        .filter(
          (run) => run.status === 'failed'
        )
        .map(
          (run) => run.event_id
        ),
      source_event_ids: runs.map(
        (run) => run.event_id
      ),
      next_step: 'ai_summary_pending'
    }
  }
];

